/* Render source-separated editorial guidance using the selected verified faction. */
(()=>{'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko,tag='span')=>`<${tag} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</${tag}>`,P=p=>L(...p,'p'),ok=r=>r?.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26',R=()=>window.RULES_DATA||{};
function rows(type,spec){return(R().fighterTypes||[]).filter(t=>ok(t)&&t.gang_type_id===type.id&&(t.id===spec.model||t.name===spec.model));}
const title=t=>L(t.name,t.name_ko||window.UKI18n?.name(t.name)||t.name);
function modelLink(t){return `<button type="button" class="gg-link" data-guide-kind="fighterTypes" data-guide-id="${E(t.id)}">${title(t)}${t.fighter_variant?` · ${E(t.fighter_variant)}`:''}</button>`;}
const qty=q=>({ 'Optional swap':['Optional replacement','교체 대안'],'Optional replacement':['Optional replacement','교체 대안'],'One leader option':['Leader option · choose one','리더 선택지 · 한 명만'],'Alternative leader':['Alternative leader · choose one','대체 리더 · 한 명만'],'About 3':['About 3','약 3명'],'About 4':['About 4','약 4명'],'Fanatic alternative':['Fanatic alternative','퍼내틱 대안']}[q]||[String(q),String(q)]);
function defaults(types,kind){const ids=new Set(types.map(t=>t.id));return [...new Set((R().fighterDefaults||[]).filter(r=>ok(r)&&ids.has(r.fighter_type_id)&&r[kind+'_id']).map(r=>r[kind+'_id']))].map(id=>(R()[kind==='skill'?'skills':'equipment']||[]).find(r=>ok(r)&&r.id===id)).filter(Boolean);}
function gearCard(spec,type,g,h){const ts=rows(type,spec);if(!ts.length)return '';const access=ts.flatMap(t=>h.equipment(t,g)),fixed=defaults(ts,'equipment'),items=spec.gear.map(name=>{const accessible=access.find(e=>e.name===name),grant=fixed.find(e=>e.name===name),other=(R().equipment||[]).find(e=>ok(e)&&e.name===name),e=accessible||grant||other;return e?{e,accessible,grant}:null;}).filter(Boolean),conditional=['Venator Gangs','Outcasts'].includes(type.name);
 return `<article class="gg-card gg-strategy-role" data-strategy-role="${E(spec.model)}"><header><h3>${L(...spec.title)}</h3><small>${L(...qty(spec.quantity))}</small></header><div class="gg-strategy-models">${ts.map(modelLink).join(' · ')}</div>${P(spec.why)}${items.length?`<div class="gg-gear">${items.map(({e,accessible,grant})=>`<span ${!accessible&&!grant||conditional?'data-strategy-conditional-equipment':''}>${h.ref('equipment',e)}${grant?` · ${L('Fixed grant','고정 지급')}`:accessible&&!conditional?` · ${E(accessible.cost)} cr`:` · ${L('Check configured access','구성 후 접근 확인')}`}</span>`).join('')}</div>`:P(['Use this model’s native profile and fixed equipment; no generic shopping list is substituted.','일반 총기 구매 목록을 대입하지 않고 이 모델의 기본 프로필·고정 장비를 사용합니다.'])}${fixed.length?`<p class="gg-caption">${L('Fixed equipment','고정 장비')}: ${fixed.map(e=>h.ref('equipment',e)).join(' · ')}</p>`:''}${ts.length>1?P(['Choose the exact profile at recruitment. These are alternatives, not multiple free models.','모집 시 정확한 프로필을 선택합니다. 복수 프로필은 대안이며 여러 모델을 무료로 받는 것이 아닙니다.']):''}</article>`;
}
function skillCard(spec,type,g,h){const ts=rows(type,spec);if(!ts.length)return '';const fixed=defaults(ts,'skill'),fixedIds=new Set(fixed.map(s=>s.id)),conditional=['Venator Gangs','Outcasts'].includes(type.name),actual=new Set(ts.flatMap(t=>h.primary(t)).map(s=>s.id)),candidates=spec.skills.map(name=>(R().skills||[]).find(s=>ok(s)&&s.name===name)).filter(s=>s&&!fixedIds.has(s.id)&&(conditional||actual.has(s.id))),free=ts.some(t=>t.free_skill===true),specialist=ts.some(t=>(t.fighter_subtypes||[]).includes('Specialist'));
 return `<article class="gg-card gg-strategy-growth" data-strategy-model="${E(spec.model)}"><h3>${L(...spec.title)}</h3><div class="gg-strategy-models">${ts.map(modelLink).join(' · ')}</div>${fixed.length?`<p>${L('Fixed grants · not your chosen starting skill','고정 지급 · 선택 시작 스킬과 별개')}: ${fixed.map(s=>h.ref('skills',s)).join(' · ')}</p>`:''}<strong class="gg-strategy-skill-label">${conditional?L('Conditional ideas after profile / set configuration','프로필·세트 구성 뒤의 조건부 후보'):free?L('Choose one starting Primary · alternatives','시작 프라이머리 1개 선택 · 대안'):L('Primary candidates when recruitment / advancement permits','프라이머리 후보 · 모집·성장 허용 시')}</strong><div class="gg-gear" data-strategy-skill-scope="${conditional?'conditional':'primary'}" data-strategy-type-ids="${E(ts.map(t=>t.id).join(','))}">${candidates.map(s=>`<span>${h.ref('skills',s)}</span>`).join('')||L('Resolve the model’s actual configured access before selecting.','선택하기 전에 모델의 실제 접근 구성을 확인하세요.')}</div>${P(spec.growth)}${specialist?P(['Choose one of this model’s permitted specialisations in recruitment. A suggested Medic or Tech role does not override its allowed list or grant all alternatives.','모집 화면에서 이 모델에 허용된 전문화 하나를 선택합니다. 메딕·테크 역할 제안이 허용 목록을 덮어쓰거나 여러 대안을 모두 지급하지 않습니다.']):''}${ts.some(t=>t.starting_power_choice)?P(['Resolve the required power choice separately from a skill choice.','필수 파워 선택은 스킬 선택과 별도로 처리합니다.']):''}</article>`;
}
function research(entry){const src=entry.sources.map(key=>window.MMFactionStrategySources?.[key]).filter(Boolean);return `<details class="gg-strategy-research"><summary>${L('Community findings, our decision & sources','커뮤니티 의견·채택 판단·출처')} <small>${src.length}</small></summary><div><h4>${L('What people recommend','사람들이 제안하는 방향')}</h4>${P(entry.community)}<h4>${L('What this guide adopts','이 가이드의 판단')}</h4>${P(entry.decision)}<h4>${L('Not copied into this recommendation','그대로 가져오지 않은 내용')}</h4>${P(entry.rejected)}<ul>${src.map(s=>`<li><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.title)} ↗</a><small>${E(s.edition)} · ${s.kind==='official tactics'?L('Official editorial tactics, not a rule import','공식 전술 해설 · 규칙 자동 추가 아님'):L('Community discussion / personal experience','커뮤니티 토론·개인 경험')}</small></li>`).join('')}</ul>${P(['Checked 31 October 2026. A discussion is not a tournament sample or an official ruling. Recommendations are this app’s editorial judgement; prices, legal access and effects still use the verified N26 catalogue. New Journal options are not enabled by a link.','검토일 2026-10-31. 토론은 대회 통계나 공식 재정이 아닙니다. 추천은 앱의 편집 판단이며 가격·접근·효과는 확인된 N26 카탈로그를 따릅니다. 새 저널 선택지는 링크가 있다고 활성화되지 않습니다.'])}</div></details>`;}
function render(g,type,h){const base=window.MMFactionStrategyData?.[type.name],e=base?.paths?.[h.plan.path]?{...base,...base.paths[h.plan.path]}:base;if(!e||!ok(type)||String(g.edition).toLowerCase()!=='n26')return null;const key=E(type.id),head=`<div class="gg-strategy-heading" data-strategy-faction="${key}"><small>${L('Faction-specific plan · community + catalogue analysis','팩션별 설계 · 커뮤니티와 카탈로그 분석')}</small><h3>${L(...e.title)}</h3>${P(e.decision)}</div>`,researchBody=research(e);
 const start=head+`<section class="gg-strategy-composition"><h4>${L('Starting structure to compare','비교할 시작 구성')}</h4>${P(e.composition)}<p class="gg-caption">${L('A tactical design, not an automatically legal or fully costed roster. Use the recruitment screen for required profiles, equipment packages and campaign conditions.','전술 설계안이며 자동 적법·전체 가격 확정 명단이 아닙니다. 필수 프로필·장비 묶음·캠페인 조건은 모집 화면에서 정합니다.')}</p></section>`+(h.plan.rows.length?`<details class="gg-strategy-budget"><summary>${L('Catalogue-priced beginner example','카탈로그로 계산한 입문 예시')}</summary><div>${h.paths}${h.roster}</div></details>`:'')+`<h4>${L('First purchases & what can wait','첫 구매와 뒤로 미룰 투자')}</h4>${P(e.purchases)}${researchBody}`;
 const gear=head+`<p class="gg-caption">${L('Choose a role and one compatible kit. Listed weapons are alternatives; a conditional label means configuration and access still need to be resolved.','역할과 호환 무장 하나를 고릅니다. 표시된 무기는 대안이며 조건부 표시는 구성·접근을 먼저 정해야 한다는 뜻입니다.')}</p><div class="gg-grid">${e.roles.map(r=>gearCard(r,type,g,h)).join('')}</div>`;
 const growth=head+`<div class="gg-grid">${e.roles.map(r=>skillCard(r,type,g,h)).join('')}</div><section class="gg-strategy-purchases"><h4>${L('Campaign development','캠페인 성장·구매 순서')}</h4>${P(e.purchases)}</section>${type.name==='Spyre Hunters'?P(['Check Spyrer hunt, servicing and rig advancement rules first. The shared N26 advancement table below is a reference where applicable, not a replacement for those special procedures.','스파이어의 사냥·정비·리그 개량 규칙을 먼저 확인하세요. 아래 공통 N26 성장 표는 해당되는 경우의 참고이며 특수 절차를 대체하지 않습니다.']):''}<details class="gg-strategy-core"><summary>${L('Shared N26 XP and advancement rules','공통 N26 경험치·성장 규칙')}</summary><div>${h.growth}</div></details>`;
 const play=head+`<ol class="gg-steps gg-strategy-steps">${e.play.map(p=>`<li>${P(p)}</li>`).join('')}</ol><aside class="gg-strategy-trap"><h4>${L('The assumption most likely to break this plan','이 운영을 망가뜨리기 쉬운 전제')}</h4>${P(e.rejected)}</aside>`;
 return {start,gear,growth,play,check:`<div class="gg-strategy-check"><h3>${L('Check against this faction’s plan','이 팩션의 설계와 대조하기')}</h3>${P(e.composition)}${P(e.rejected)}</div>`};
}
window.MMFactionStrategy={render,models:rows};
})();
